targets.expr:
sum by (namespace, container) (
  rate(container_cpu_usage_seconds_total{namespace=~"$namespace", container!="", container!="POD"}[5m])
)
/
sum by (namespace, container) (
  kube_pod_container_resource_limits{namespace=~"$namespace", resource="cpu"}
) * 100

sum by (namespace, container) (
  container_memory_working_set_bytes{namespace=~"$namespace", container!="", container!="POD"}
)
/
sum by (namespace, container) (
  kube_pod_container_resource_limits{namespace=~"$namespace", resource="memory"}
) * 100

sum by (namespace, pod) (
  rate(container_cpu_usage_seconds_total{namespace=~"$namespace", container!="", container!="POD"}[5m])
)
/
sum by (namespace, pod) (
  kube_pod_container_resource_limits{namespace=~"$namespace", resource="cpu"}
) * 100

sum by (namespace, pod) (
  container_memory_working_set_bytes{namespace=~"$namespace", container!="", container!="POD"}
)
/
sum by (namespace, pod) (
  kube_pod_container_resource_limits{namespace=~"$namespace", resource="memory"}
) * 100
